(() => {
'use strict';
const D=window.DASHBOARD_DATA;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(v,d=0)=>Number.isFinite(Number(v))?new Intl.NumberFormat('tr-TR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(v)):'—';
const pct=(v,d=2)=>nf(Number(v)*100,d)+'%';
const tl=v=>nf(v,0)+' TL';
const names={tl_vadesiz:'TL vadesiz mevduat',tl_vadeli:'TL vadeli mevduat',kredi:'Kredi ortalaması'};
const shortNames={tl_vadesiz:'TL vadesiz',tl_vadeli:'TL vadeli',kredi:'Kredi'};
const groups={ALL:'Tüm şubeler',UC_BUYUK_IL:'İstanbul / Ankara / İzmir',DIGER_ILLER:'Diğer iller'};
const models={ay_sonu_koru:'Ay sonu stokunu koru',son_ayi_koru:'Son ayı koru',egitim_ortalamasi:'Eğitim ortalaması'};
const featureGroups={kapasite:'Kapasite',demografi:'Demografi',gelir_profili:'Gelir profili',iliski_aktivite:'İlişki / aktivite',bolgesel_kosullar:'Bölgesel koşullar',takvim:'Takvim',varlik_segmenti:'Varlık / segment',gecmis_bakiye:'Geçmiş bakiye'};
const featureLabels={musteri_sayisi:'Müşteri sayısı',personel_fte_sentetik:'Personel kapasitesi',ortalama_aylik_gelir_tl:'Ortalama aylık gelir',ortalama_yas:'Ortalama yaş',yas_std:'Yaş dağılımı',yas_35_alti_orani:'35 yaş altı oranı',yas_60_ustu_orani:'60 yaş üzeri oranı',bakim_yukumlulugu_ort:'Bakmakla yükümlü kişi',yuksek_egitim_orani:'Yüksek eğitim oranı',egitim_bilinmiyor_orani:'Eğitim bilgisi eksik oranı',evli_orani:'Evli müşteri oranı',kaynak_ust_gelir_orani:'Üst gelir grubu oranı',kaynak_gelir_bilinmiyor_orani:'Gelir bilgisi eksik oranı',kaynak_pasif_ay_ort:'Geçmiş pasif ay ortalaması',mobil_aktif_orani:'Mobil aktiflik oranı',maas_musterisi_orani:'Maaş müşterisi oranı',emekli_maasi_orani:'Emekli maaşı oranı',ana_banka_orani:'Ana banka ilişkisi',ekonomik_yapi_sentetik:'Bölgenin ekonomik yapısı',sosyoekonomik_skor_sentetik:'Sosyoekonomik skor',rakip_sube_sayisi_sentetik:'Rakip şube sayısı',nufus_sentetik:'Bölge nüfusu',takvim_ay_sin:'Takvim · ay sinüsü',takvim_ay_cos:'Takvim · ay kosinüsü',zaman_indeksi:'Zaman indeksi',portfoy_musteri_orani:'Portföy müşterisi payı',segment_s1_orani:'S1 müşteri payı',segment_s2_orani:'S2 müşteri payı',segment_s5_orani:'S5 müşteri payı',ortalama_varlik_tl:'Ortalama banka varlığı'};
for(const t of Object.keys(names))Object.assign(featureLabels,{[t+'_bakiye_t']:shortNames[t]+' · mevcut bakiye',[t+'_bakiye_t_eksi_1']:shortNames[t]+' · önceki ay',[t+'_son3ay_ort_tl']:shortNames[t]+' · son 3 ay',[t+'_son_ay_buyume']:shortNames[t]+' · son ay büyüme'});
Object.assign(featureLabels,{ortalama_iliski_skoru:'Müşteri ilişki skoru',yeni_musteri_sayisi:'Yeni müşteri',ayrilan_musteri_sayisi:'Bankadan ayrılan müşteri',devir_giris_musteri_sayisi:'Başka şubeden gelen müşteri',devir_cikis_musteri_sayisi:'Başka şubeye devredilen müşteri',diger_bankaya_kaynak_cikisi_tl:'Diğer bankalara kaynak çıkışı',diger_bankadan_kaynak_girisi_tl:'Diğer bankalardan kaynak girişi',musteri_gun:'Aktif müşteri-günü',ay_ici_hizmet_verilen_musteri_sayisi:'Ay içi hizmet verilen müşteri',musteri_sayisi_degisim:'Aktif müşteri sayısı değişimi',musteri_gun_ay_sonu_orani:'Müşteri-günü / ay sonu oranı'});
for(const t of Object.keys(names))Object.assign(featureLabels,{[t+'_ay_sonu_bakiye_tl']:shortNames[t]+' · ay sonu stoku',[t+'_kapanis_ortalama_farki_tl']:shortNames[t]+' · kapanış / ortalama farkı',[t+'_devir_net_degisim_tl']:shortNames[t]+' · net devir stoku',[t+'_devir_haric_net_degisim_tl']:shortNames[t]+' · devir dışı stok değişimi'});
const iconPaths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',pipeline:'<rect x="2" y="9" width="6" height="6" rx="1.5"/><rect x="16" y="3" width="6" height="6" rx="1.5"/><rect x="16" y="15" width="6" height="6" rx="1.5"/><path d="M8 12h4V6h4M12 12v6h4"/>',book:'<path d="M12 5C9 2 5 3 3 4v16c3-1.5 6-1.5 9 0 3-1.5 6-1.5 9 0V4c-3-1.5-6-1.5-9 1Zm0 0v15"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',chart:'<path d="M3 3v18h18M7 15l4-5 4 3 6-8"/>',sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l3 3h6a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4"/>',filter:'<path d="M3 4h18l-7 8v7l-4 2v-9Z"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 4v6h6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m1-16a3 3 0 0 1 0 6m3 10v-2a6 6 0 0 0-3-5"/>',layers:'<path d="m12 2 10 5-10 5L2 7Zm-10 10 10 5 10-5M2 17l10 5 10-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5M14 3l-4 18"/>',file:'<path d="M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9Zm0 0v7h7M7 13h10M7 17h7"/>'};
const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.info}</svg>`;
const badge=(text,type='')=>`<span class="badge ${type}"><span class="badge-dot"></span>${esc(text)}</span>`;
const nav=[['overview','grid','Genel bakış'],['pipeline','pipeline','Pipeline'],['selection','sliders','Değişken seçimi'],['model-selection','sliders','Ana model seçimi'],['clustering','layers','Şube kümeleri'],['dea','chart','Verimlilik'],['methodology','book','Metodoloji'],['data','database','Veri ve ayrımlar'],['benchmark','layers','Algoritma karşılaştırması'],['automl','sliders','FLAML AutoML'],['files','folder','Dosyalar']];
const headings={dea:['Küme içi verimlilik analizi','Çıktı odaklı CRS-DEA, VRS duyarlılığı, emsal şubeler ve ürün bazında iyileştirme mesafesi.'],'model-selection':['Ana kümeleme modeli seçimi','Yöntem ve senaryo için ortak puan, kalite koşulları ve ayrı dönem kontrolü.'],clustering:['Şube kümeleri ve karşılaştırma','URF + K-Medoids başlangıcı, alternatifler, müşteri profilleri ve aylık kararlılık.'],selection:['Dinamik değişken seçimi','Alan sözlüğü, veri kontrolleri, dönem kararlılığı ve kümeleme için ortak aday seti.'],automl:['FLAML AutoML','Bütün göstergeler ve şube grupları için tek ortak algoritma; V4 doğrulama ve test karşılaştırması.'],benchmark:['Algoritma karşılaştırması','LightGBM, Random Forest ve CatBoost: aynı veri, aynı dönemler, ölçülen hata ve süre.'],overview:['Model laboratuvarı','Veriden modele, her adımı ve kararın dayanağını inceleyin.'],pipeline:['Pipeline incelemesi','Tamamlanan ve planlanan aşamaları, girdi ve çıktılarıyla izleyin.'],methodology:['Modelin çalışma yöntemi','Tahmin sorusu, veri kullanımı ve değerlendirme kararları tek yerde.'],data:['Veri ve zaman ayrımları','Müşteri verisinden şube-ay tablosuna, geçmişten geleceğe doğru.'],files:['Çalışma dosyaları','Veriyi, modelleri, metodolojiyi ve Python kodlarını indirin.']};
const selectionBlocked=!!(D.auto_cluster_selection?.matches_current_grid&&!D.auto_cluster_selection.decision.selected);
let state={deaGroup:'ALL',deaCluster:'ALL',deaIndicator:'',deaSearch:'',deaBranch:'',clusterScenario:'',clusterMethod:'',clusterGroup:'ALL',clusterPeriod:'',clusterSearch:'',benchmarkDataset:D.comparison_v4?'v4':'v3',benchmarkView:D.comparison_v4?'hareketli':'gecikmeli',benchmarkAlgorithm:'catboost',benchmarkImportance:'permutation',selectionStatus:'all',selectionFamily:'all',selectionSearch:'',route:'overview',target:'tl_vadesiz',group:'ALL',split:'TEST',step:2};
const stages=[
 {id:1,title:'Veri hazırlama',short:'Veri hazırlama',status:'Tamamlandı',desc:'Müşteri profilleri ve aylık ürün gerçekleşmeleri aynı şube-ay düzeyinde birleştirildi. Hedef etiketleri sonraki aya kaydırıldı; geçmiş bakiye pencereleri yalnızca bilinen aylardan üretildi.',inputs:['V4 müşteri hareketleri, 200 şube, 26 sentetik ay','Mevduat, kredi, yatırım, kart ve ilişki alanları','Şube kapasitesi ve bölgesel test göstergeleri'],outputs:['4.600 etiketli şube-ay gözlemi','3.400 eğitim, 600 doğrulama, 600 test satırı','Ocak 2027 için 200 tahmin girdisi'],code:'# Bir ay ileri etiket\nX = t_ayinda_bilinen_bilgiler\ny = t_artı_1_ayinin_ortalama_bakiyesi\n# Şube ve müşteri kimlikleri modele girmez',actions:[['data','Veri ayrımlarını incele'],['files','Eğitim setini indir']]},
 {id:2,title:'Dinamik değişken seçimi',short:'Değişken seçimi',status:'Tamamlandı',desc:'Alan sözlüğü kaynak sütunlarını, kullanım rollerini ve zamanında bilinirliği tanımlar. Eğitim verisinde kalite/korelasyon kontrolünden geçen adaylar, geçmiş dönemlerde CatBoost ve permütasyon kararlılığıyla değerlendirilir. Göstergelerin eşit ağırlıklı katkısıyla ortak aday seti oluşturulur.',inputs:['Sözlükte tanımlı müşteri yapısı ve potansiyel adayları','Tarihli şube veya müşteri-ay verisi','Açıklanacak üretim göstergeleri; X içinde üretim toplamı yok'],outputs:['Seçilen/elenen alanlar ve karar gerekçeleri','Dondurulmuş alan sırası, medyanlar ve kategori sözlüğü','Son ay kümeleme girdisi ve aylık dağılım kontrolleri'],code:'# Alan adları ve sayısı sözlükten gelir\nadaylar = sozluk.kumeleme_adaylari\n# Kalite + korelasyon + dönemsel CatBoost katkısı\n# Ortak şema kaydedilir; kümeleme sonraki aşamadır.',actions:[['selection','Dinamik değişken seçimi'],['automl','Önceki tahmin deneyi']]},
 {id:3,title:'URF + K-Medoids ve alternatifler',short:'Şube kümeleri',status:selectionBlocked?'Uygun aday yok':D.clustering?.matches_current_selection?'Tamamlandı':'Sırada',desc:'URF + K-Medoids, Gower + K-Medoids ve uygulanabilirse K-Prototypes karşılaştırılır. Ana yöntem, alan oranı ve küme sayısı doğrulama performansı ve kalite koşullarıyla ortak seçilir. Referans dönemi sabit tutulur; yeni aylara atama ve aylık yeniden kümeleme ayrı değerlendirilir.',inputs:['Doğrulanmış ortak değişken şeması','Şube başına tek satırlık aylık kesitler','İki coğrafi grupta aynı üç kümeleme yöntemi'],outputs:['Şube küme atamaları ve temsilci şubeler','Kaynak birimlerinde müşteri/küme profilleri','Aylık, tohum ve alt örneklem kararlılığı'],code:'# Orijinal başlangıç yöntemi\nuzaklik = sqrt(1 - URF_yaprak_yakinligi)\nkumeler = PAM(uzaklik, k)\n# Gower/PAM ve K-Prototypes aynı girdilerle kıyaslanır.',actions:[['model-selection','Ana model seçimini incele'],['clustering','Şube kümelerini incele']]},
 {id:4,title:'Yöntem ve küme senaryosu seçimi',short:'Ana model seçimi',status:selectionBlocked?'Uygun aday yok':D.auto_cluster_selection?.matches_current_grid?'Tamamlandı':'Planlandı',desc:'Yöntem, alan oranı ve toplam küme sayısı birlikte değerlendirildi. Kalite ve kararlılık koşullarını geçen adaylardan bir ortak seçim yapıldı. Sonraki tarihsel kontrol dönemi seçim puanına katılmadı.',inputs:['URF/PAM, Gower/PAM ve uygulanabilirse K-Prototypes','%25/%50 alan seçimi ve 5/7 toplam küme','Doğrulama dönemi ve referans kararlılık ölçüleri'],outputs:['Bütün göstergeler ve gruplarda ortak yöntem/senaryo','Aday puanları ve elenme gerekçeleri','Ayrı dönem değerlendirmesi'],code:'# Kalite koşullarını geçen tek ortak aday\nana_model = en_yuksek_uygun_puan(adaylar)\n# Uygun aday yoksa ana model seçilmez.',actions:[['model-selection','Ana model seçimi']]},
 {id:5,title:'DEA ile verimlilik analizi',short:'DEA analizi',status:D.dea?.active?'Tamamlandı':D.dea?'Tarihsel sonuç':'Planlandı',desc:'Seçilen ana modelin emsal kümelerinde, aynı ayın müşteri kitlesi ve ürün ortalamaları karşılaştırılır. Çıktı odaklı CRS-DEA, ikinci aşama ürün boşlukları ve VRS duyarlılığı birlikte raporlanır.',inputs:['Doğrulanmış ana yöntemin güncel şube küme atamaları','Aylık ortalama aktif müşteri: müşteri-gün / takvim günü','TL vadesiz, TL vadeli ve kredi aylık ortalamaları'],outputs:['Küme içi göreli verimlilik ve radyal artış mesafesi','Emsal şubeler, katsayılar ve ürün projeksiyonları','Küme boyutu ve ölçek varsayımı kontrolleri'],code:'# Her kümede aynı ayın gözlemleri\nphi = max_output_expansion(X, Y, peer_cluster)\nverimlilik = 1 / phi\n# Projeksiyon bir aylık büyüme tahmini veya banka hedefi değildir.',actions:[['dea','Verimlilik sonuçlarını incele']]},
 {id:6,title:'Banka hedefini şubelere dağıtma',short:'Hedef dağıtımı',status:'Planlandı',desc:'Aralık 2026 aylık ortalamaları üzerinden Ocak 2027 banka üst toplamları hazır. Şube hedefleri, emsal karşılaştırmaları ve potansiyel değerlendirmesi tamamlandıktan sonra bu toplamlara uyarlanacak.',inputs:['TL vadesiz +%15, TL vadeli +%10, kredi +%5','Aralık 2026 aylık ortalamaları','Küme ve DEA sonuçları'],outputs:['Hazır: Ocak 2027 banka üst toplam hedefleri','Planlanan: gösterge bazında şube hedefleri','Planlanan: banka hedefiyle toplam mutabakatı'],code:'# Banka hedefleri hazır\nhedef_vadesiz = aralik_vadesiz * 1.15\nhedef_vadeli  = aralik_vadeli  * 1.10\nhedef_kredi   = aralik_kredi   * 1.05\n# Model tahmini ve banka bütçesi farklı alanlardır.',actions:[['files','Çalışma dosyaları']]}
];

function currentMetrics(model){const pool=state.group==='ALL'?D.automl.total_metrics:D.automl.metrics;return pool.find(x=>x.gosterge===state.target&&x.model===model&&x.split===state.split&&(state.group==='ALL'||x.sube_grubu===state.group));}
function currentAlgorithm(){return {lgbm:'LightGBM',rf:'Random Forest',catboost:'CatBoost'}[D.automl.global_selection.selected_learner];}
function currentGroups(){return state.group==='ALL'?['UC_BUYUK_IL','DIGER_ILLER']:[state.group];}

function metricContext(){return `${esc(names[state.target])} · ${esc(groups[state.group])} · ${state.split==='TEST'?'Test':'Doğrulama'}`;}
function kpis(all=false){const group=all?'ALL':state.group;const branches=group==='ALL'?200:group==='UC_BUYUK_IL'?80:120;return `<div class="kpi-grid">${[['Şube kapsamı',nf(branches),group==='ALL'?'80 büyük il grubu · 120 diğer':'Seçili şube grubu'],['Etiketli gözlem',nf(branches*23),'23 hedef ayı · şube-ay düzeyi'],['Ortak algoritma',currentAlgorithm(),'Üç gösterge ve iki grupta aynı'],[D.feature_selection?'Kümeleme aday seti':'Tahmin deneyi girdileri',D.feature_selection?nf(D.feature_selection.manifest.selected_count)+' alan':nf(D.automl.manifest.feature_count)+' alan',D.feature_selection?'Sözlük ve dönem kararlılığıyla seçildi':'Müşteri, hareket ve ay sonu stoku']].map(([label,value,note])=>`<div class="kpi"><div class="kpi-head"><span>${label}</span></div><div class="kpi-value">${value}</div><small>${note}</small></div>`).join('')}</div>`;}
function splitView(){return `<div class="timeline" role="img" aria-label="3400 eğitim, 600 doğrulama, 600 test satırı"><div class="train"></div><div class="valid"></div><div class="test"></div></div><div class="split-legend">${[['EĞİTİM','3.400','Şub 2025 – Haz 2026','#315f83'],['DOĞRULAMA','600','Tem – Eyl 2026','#78b4a3'],['TEST','600','Eki – Ara 2026','#d6b06e']].map(([label,n,period,c])=>`<div><span><i class="dot" style="background:${c}"></i>${label}</span><strong>${n}</strong><small>${period}<br>Hedef ayları</small></div>`).join('')}</div>`;}
function overview(){const selectionCard=D.feature_selection?`<section class="card space-bottom"><div class="card-head"><div><h2>Kümeleme için ${nf(D.feature_selection.manifest.selected_count)} ortak aday alan</h2><p>${nf(D.feature_selection.manifest.candidate_count)} tanımlı aday · ${nf(D.feature_selection.manifest.eligible_count)} kalite sonrası alan. Kararlar ve gerekçeler kayıtlı.</p></div><a class="button small" href="#selection">Değişken seçimini incele</a></div><div class="card-body"><p>Seçim girdisi hazır. Aynı alanlarla URF ve alternatifler çalıştırıldı; sonuçlar Şube kümeleri ekranındadır. Yeni veri sözlüğe eşlenir.</p></div></section>`:'';const current=currentMetrics('flaml_automl'),ref=currentMetrics('ay_sonu_koru');return selectionCard+kpis()+`<section class="card space-bottom"><div class="card-head"><div><h2>Bütün göstergelerde ortak model: ${currentAlgorithm()}</h2><p>TL vadesiz, TL vadeli ve kredide; iki şube grubunda aynı algoritma kullanılır.</p></div><a class="button small" href="#automl">FLAML sonuçlarını incele</a></div><div class="card-body text-detail"><p>Seçim, üç göstergenin banka geneli doğrulama WAPE ortalamasına dayanır. Gösterge ve grup için ayrı eğitimler vardır; algoritma ailesi değişmez. Referanslar yalnızca karşılaştırmadır.</p><div class="metric-strip"><div class="metric-cell"><small>${currentAlgorithm()} · ${shortNames[state.target]} WAPE</small><strong>${pct(current.wape,3)}</strong><div class="metric-desc">${groups[state.group]} · ${state.split==='TEST'?'tarihsel test':'doğrulama'}</div></div><div class="metric-cell"><small>Ay sonu referansı · WAPE</small><strong>${pct(ref.wape,3)}</strong><div class="metric-desc">Aynı ${nf(ref.n)} şube-ay üzerinde</div></div><div class="metric-cell"><small>Ortak seçim ölçütü</small><strong>3 gösterge</strong><div class="metric-desc">Her gösterge eşit ağırlıklı</div></div></div><p class="inline-note">Ekim–Aralık 2026 daha önce incelendi; test sonuçları yeniden kullanılan tarihsel karşılaştırmadır.</p></div></section><section class="card pipeline-overview"><div class="card-head"><div><h2>Modelin uçtan uca akışı</h2><p>${selectionBlocked?'Veri ve değişken seçimi hazır · kümeleme kalite koşullarını sağlayan aday aranıyor':'Veri hazırlama, değişken seçimi, kümeleme ve DEA · banka hedef dağıtımı sırada'}</p></div><a class="link-button" href="#pipeline">Pipeline’ı incele</a></div><div class="pipeline-track">${stages.map(x=>`<button class="pipeline-mini" data-open-step="${x.id}" aria-label="${x.id}. aşama: ${x.title}, ${x.status}"><span class="step-circle ${(x.status==='Tamamlandı')?'done':''}">${(x.status==='Tamamlandı')?icon('check',13):x.id}</span><span class="step-title"><strong>${x.short}</strong><small>${x.status}</small></span></button>`).join('')}</div></section><div class="two-col"><section class="card"><div class="card-head"><h2>Zaman sıralı veri ayrımı</h2></div><div class="card-body">${splitView()}<a class="link-button" href="#data">Veri kapsamını incele</a></div></section><section class="card"><div class="card-head"><h2>Algoritmalar ve değişken önemleri</h2></div><div class="card-body text-detail"><p>LightGBM, Random Forest ve CatBoost aynı karşılaştırma ekranında yer alır. Önceki deneylerin hata, süre ve değişken önemleri burada incelenir.</p><p>Bu önemler önceki karşılaştırma modellerine aittir. Yeni yapısal adayların katkıları Değişken seçimi ekranında gösterilir.</p><a class="button secondary small" href="#benchmark">Algoritma karşılaştırmasını aç</a></div></section></div>`;}
function pipeline(){const s=stages.find(x=>x.id===state.step)||stages[1];return `<div class="stage-layout"><div class="stage-list">${stages.map(x=>`<button class="stage-select ${x.id===s.id?'active':''}" data-stage="${x.id}" aria-pressed="${x.id===s.id}"><span class="step-circle ${(x.status==='Tamamlandı')?'done':''}">${(x.status==='Tamamlandı')?icon('check',13):x.id}</span><span><strong>${x.title}</strong><small>Aşama ${String(x.id).padStart(2,'0')}</small></span>${badge(x.status,(x.status==='Tamamlandı')?'success':'planned')}</button>`).join('')}</div><article class="card stage-detail"><div class="overline">AŞAMA ${String(s.id).padStart(2,'0')} / 06 &nbsp; ${badge(s.status,(s.status==='Tamamlandı')?'success':'planned')}</div><h2 class="stage-title">${s.title}</h2><p>${s.desc}</p><div class="detail-columns"><div><h3>Girdiler ve kararlar</h3><ul>${s.inputs.map(x=>`<li>${x}</li>`).join('')}</ul></div><div><h3>Çıktılar</h3><ul>${s.outputs.map(x=>`<li>${x}</li>`).join('')}</ul></div></div><pre class="code-box">${esc(s.code)}</pre>${s.id===6?budgetCards():''}<div class="stage-actions">${s.actions.map(([route,text],i)=>`<a class="button ${i?'secondary':''}" href="#${route}">${text} ${icon('arrow',13)}</a>`).join('')}</div></article></div>`;}
function budgetCards(){const budgets=D.budgets_v4||D.budgets;return `<div class="budget-grid">${budgets.map(b=>`<div class="budget-item"><small>${esc(b.gosterge_adi)}</small><strong>${nf(b.hedef_aylik_ortalama_tl/1e6,2)} <small>milyon TL</small></strong><span>Aralık ortalamasına +${pct(b.artis_orani,0)}</span></div>`).join('')}</div><p class="footnote">${D.budgets_v4?'V4 Aralık 2026 referansıyla':'V3 Aralık 2026 referansıyla'} Ocak 2027 banka üst toplamlarıdır. Şube dağıtımı ve DEA henüz çalıştırılmadı.</p>`;}

function methodology(){const sections=[
 ['Tahmin ve veri kapsamı',`<p>t ayının bilinen müşteri profili, ürün hareketleri ve ay sonu stokuyla t+1 ayının aylık ortalama bakiyesi tahmin edilir. Model birimi şube-aydır. TL vadesiz, TL vadeli ve KMH dahil kredi izlenir; kart borcu ayrı tutulur.</p><p>V4 dinamik verisinde yeni müşteriler, şube devirleri, bankadan ayrılmalar ve dış kaynak giriş/çıkışları bulunur. Gelecek ayın gerçekleşmiş olayları girdi değildir.</p>`],
 ['Bütün göstergelerde tek algoritma',`<p>Ortak seçilen algoritma <strong>${currentAlgorithm()}</strong>. Üç gösterge ve iki şube grubunda aynı aile kullanılır; gösterge/grup için ayrı eğitim ve parametre setleri vardır.</p><p>Önceki altı FLAML aramasından LightGBM, Random Forest ve CatBoost adayları yeniden eğitildi. Her algoritma için önce şube grupları birleştirilerek gösterge WAPE hesaplandı; ardından üç gösterge eşit ağırlıkla ortalandı. En düşük ortalamalı tek algoritma seçildi. Referanslar yalnızca karşılaştırma içindir.</p>`],
 ['49 alan ve tahminin kurulması',`<p>25 yapısal alanlı ve 34 geçmiş bakiyeli deneyler karşılaştırma ekranında korunur. Önceki tahmin deneyi, ${D.automl.manifest.feature_count} alanlı hareket görünümünü kullanır: müşteri yapısı, kapasite, geçmiş bakiyeler, müşteri hareketleri ve ilgili göstergenin kapanış stoku.</p><pre class="code-box">fark = gelecek_ay_ortalaması − mevcut_ay_sonu_stoku
tahmin = max(0, mevcut_ay_sonu_stoku + model(fark))</pre><p>Kimlikler, gelecek gerçekleşmeler ve banka büyüme bütçesi model girdisi değildir. HP/segment payları mevcut ayın varlık dağılımından gelir.</p>`],
 ['Zaman ayrımı ve model kayıtları',`<p>3.400 eğitim satırı: Şubat 2025–Haziran 2026 hedef ayları. 600 doğrulama: Temmuz–Eylül. 600 tarihsel test: Ekim–Aralık 2026. Rastgele satır bölünmez.</p><p>Algoritma seçimi yalnızca doğrulama tahminlerine dayanır ve test değerlendirmesinden önce kaydedilir. Test için eğitim + doğrulama, Ocak 2027 tahmini için tüm etiketli dönemlerle ayrı modeller eğitilir. Ekim–Aralık daha önce görüldüğünden el değmemiş test iddiası yoktur.</p><p>30 paket (18 aday doğrulama, 6 ortak değerlendirme, 6 ortak Ocak modeli) yeniden yüklenerek kontrol edildi. Arama kayıtları yeniden kullanıldı; yeni arama yapılmadı.</p>`],
 ['Karşılaştırma ve değişken önemleri',`<p>Üç algoritmanın hata, süre, parametre ve önemleri <a class="link-button" href="#benchmark">Algoritma karşılaştırması</a> ekranında birlikte sunulur. V3/V4 ve özellik görünümü seçilebilir.</p><p>Ortak permutation ölçüsü ile modellerin kendi önem tanımları ayrı gösterilir. Buradaki önemler önceki manuel karşılaştırma modellerine aittir. Önceki stok tahmin modelinin önemleri bu kapsamda yeniden hesaplanmadı. Yapısal adaylar için yeni dönemsel katkılar Değişken seçimi ekranındadır.</p>`],
 ['HP, emsal grupları ve hedef dağıtımı',`<p>HP müşterinin havuz/portföy durumudur. Sentetik segment eşikleri müşterinin varlığına göre aylık uygulanır; banka genelinde havuz/portföy müşteri sayısı yaklaşık 15’tir. İstanbul/Ankara/İzmir 80, diğer iller 120 şubedir.</p><p>URF/K-Medoids ve alternatif karşılaştırmaları tamamlandı. DEA sonuçları Verimlilik ekranındadır. Şube hedef dağıtımı sıradaki aşamadır. Tahmin hatası veya değişken önemi, verimliliği ve adil hedef dağıtımını tek başına belirlemez. Vadesiz +%15, vadeli +%10, kredi +%5 banka bütçeleri tahminlerden ayrı tutulur.</p><p>Finansallar ve çevresel koşullar sentetiktir; gerçek veriyle ileriye dönük izleme gerekir.</p>`]
 ];return (D.dea?`<section class="card space-bottom"><div class="card-head"><div><h2>Çıktı odaklı CRS-DEA</h2><p>${esc(D.dea.manifest.as_of)} · küme içi aynı ay karşılaştırması · VRS duyarlılığı</p></div><a class="button secondary small" href="downloads/dea_methodology.md" download>DEA metodolojisi ve kaynakları</a></div><div class="card-body text-detail"><p>Girdi alanları ve üç çıktı sözlükte tanımlıdır. Skor 1/φ, ortak radyal mesafe φ−1 olarak hesaplanır; ikinci aşama ek ürün boşluklarını verir. Emsal sayısı ön kontrolünü geçemeyen kümelerde skor üretilmez. Projeksiyonlar banka bütçesi veya gelecek ay tahmini değildir.</p><a class="link-button" href="#dea">Verimlilik sonuçlarını incele</a></div></section>`:'')+(D.clustering?`<section class="card space-bottom"><div class="card-head"><div><h2>URF başlangıcı ve kümeleme karşılaştırması</h2><p>Referans ${esc(D.clustering.manifest.reference_period)} · 6/11 alanlı senaryolar · ${nf(D.clustering.manifest.methods.length)} yöntem</p></div><a class="button secondary small" href="downloads/clustering_methodology.md" download>Kümeleme metodolojisi</a></div><div class="card-body text-detail"><p>URF gerçek ve bağımsız karıştırılmış yapay şubeleri ayırır; ortak yaprak oranından uzaklık çıkarılır ve PAM ile kümelenir. Alternatifler Gower + K-Medoids ve K-Prototypes'tir. Referans modelleri sabittir; hangi yöntem ve k senaryosunun ana model olacağı ayrı doğrulama aylarında seçilir. Karardan sonraki dönem seçime katılmaz.</p><p>Sabit atama ile aylık yeniden kümeleme ayrı raporlanır. Küme boyutu sınırı pilot kuralıdır; DEA yeterliliği henüz değerlendirilmedi.</p><a class="link-button" href="#clustering">Kümeleri incele</a></div></section>`:'')+(D.feature_selection?`<section class="card space-bottom"><div class="card-head"><div><h2>Dinamik değişken seçimi</h2><p>Sözlükten okunan alanlar · kalite/korelasyon kontrolü · dönemsel CatBoost önemleri · ortak şema</p></div><a class="button secondary small" href="downloads/selection_methodology.md" download>Seçim metodolojisi</a></div><div class="card-body text-detail"><p>Güncel seçim ${nf(D.feature_selection.manifest.selected_count)} alan içerir. Son seçim etiket ayı ${esc(D.feature_selection.manifest.selection_end)}. Son ${nf(D.feature_selection.manifest.holdout_months)} ay seçime katılmadı. Dondurulmuş şema sonraki aylara yeniden fit edilmeden uygulanabilir.</p><a class="link-button" href="#selection">Alan kararlarını incele</a></div></section>`:'')+`<div class="section-title"><div><h2>Önceki ortak tahmin modelinin metodolojisi</h2><p>V4 · ${currentAlgorithm()} · bütün göstergelerde aynı algoritma</p></div><a class="button secondary small" href="downloads/flaml_metodoloji.md" download>Metodolojiyi indir</a></div><div class="method-accordion">${sections.map(([title,body],i)=>`<details ${i<2?'open':''}><summary>${title}</summary><div class="accordion-body">${body}</div></details>`).join('')}</div>`;}
function dataPage(){const m=D.data_manifest_v4;const rows=D.splits.map(r=>`<tr><td>${r.split}</td><td>${r.ilk_ozellik_ayi} → ${r.son_ozellik_ayi}</td><td>${r.ilk_hedef_ayi} → ${r.son_hedef_ayi}</td><td class="num">${nf(r.satir)}</td><td class="num">${r.sube}</td></tr>`).join('');return kpis(true)+`<section class="card space-bottom"><div class="card-head"><div><h2>V4 veri akışı ve zaman ayrımı</h2><p>${nf(m.branches)} şube · ${m.months} ay · bir ay ileri etiket</p></div>${badge('Kontroller geçti','success')}</div><div class="card-body">${splitView()}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ayrım</th><th>Bilinen özellik ayları</th><th>Tahmin edilen hedef ayları</th><th class="num">Şube-ay</th><th class="num">Şube</th></tr></thead><tbody>${rows}<tr><td>FORECAST</td><td>2026-12</td><td>2027-01 · etiket yok</td><td class="num">200</td><td class="num">200</td></tr></tbody></table></div></section><div class="two-col"><section class="card"><div class="card-head"><h2>Aylık müşteri hareketleri</h2></div><div class="card-body text-detail"><p>${nf(m.registered_customers)} kayıtlı müşteri, son ay ${nf(m.latest_active_customers)} aktif müşteri. ${nf(m.customer_month_rows)} müşteri-ay ve ${nf(m.event_rows)} hareket kaydı.</p><p>${nf(m.event_counts.SUBE_DEVRI)} şube devri, ${nf(m.event_counts.YENI_MUSTERI)} yeni müşteri, ${nf(m.event_counts.BANKADAN_TAM_AYRILMA)} bankadan tam ayrılma bulunur. Devirler banka toplam stokunu değiştirmez.</p><p>Aylık bakiye ortalamaları gün ağırlıklıdır; şube özellikleri ilgili ayın aktif müşteri kitlesinden hesaplanır.</p></div></section><section class="card"><div class="card-head"><h2>Model girdisi ve HP</h2></div><div class="card-body text-detail"><p>${nf(m.branch_month_rows)} ham şube-aydan 4.600 etiketli satır ve Ocak 2027 için 200 tahmin girdisi oluşturulur. İlk iki ay geçmiş pencereyi kurar.</p><p>Önceki tahmin deneyinde ${D.automl.manifest.feature_count} alan kullanıldı. Yeni kümeleme aday setinin alan sayısı sözlük ve seçim sonucundan okunur. HP ve segment, aylık sentetik varlık eşikleriyle hesaplanır; havuz/portföy müşteri sayısı yaklaşık 15’tir.</p><p>Kimlikler ve gelecek ayın gerçekleşmeleri girdi değildir.</p><a class="link-button" href="downloads/v4_ozellik_sozlugu.csv" download>V4 özellik sözlüğünü indir</a></div></section></div>`;}
function filesPage(){return `<section class="card space-bottom"><div class="card-head"><div><h2>Çalışma paketinin içeriği</h2><p>Güncel ortak model ve önceki algoritma deneyleri aynı dosya alanında.</p></div>${badge('Kaydedilmiş çıktılar','success')}</div><div class="card-body text-detail"><p>Dinamik değişken seçimi paketi güncel alan sözlüğünü, şemayı ve gerekçeleri içerir. Önceki FLAML tahmin paketinde ortak algoritma seçimi ve 30 model kaydı vardır. V3/V4 algoritma karşılaştırmaları ile ilk deneyin dosyaları tarihsel kayıt olarak korunur. Güncel modelin metodolojisi ve sonuçları FLAML başlıklı dosyalardadır.</p><p>Dashboard filtreleri model eğitmez veya banka bütçesini değiştirmez. Yeni sonuçlarla güncellemek için Python pipeline’ı çalıştırıp dashboard veri anlık görüntüsünü yeniden oluşturmak gerekir.</p></div></section><div class="download-grid">${[...D.downloads.filter(f=>f.name.startsWith('clustering_')),...D.downloads.filter(f=>f.name.startsWith('selection_')),...D.downloads.filter(f=>f.name.startsWith('flaml_')),...D.downloads.filter(f=>!f.name.startsWith('flaml_')&&!f.name.startsWith('selection_')&&!f.name.startsWith('clustering_'))].map(f=>`<article class="download-card"><div class="download-top"><span class="file-icon">${icon(f.kind.includes('PY')?'code':f.kind==='CSV'?'database':'file',21)}</span><span class="badge">${esc(f.kind)}</span></div><h3>${esc(f.title)}</h3><p>${esc(f.description)}</p><div class="download-bottom"><small>${f.bytes>=1e6?nf(f.bytes/1e6,1)+' MB':nf(f.bytes/1e3,0)+' KB'}</small><a class="link-button" href="${esc(f.path)}" download="${esc(f.name)}">Dosyayı indir ${icon('download',14)}</a></div></article>`).join('')}</div>`;}

// Included inside app.js's scope by the source update below.
const algorithms={lightgbm:'LightGBM',random_forest:'Random Forest',catboost:'CatBoost'};
function benchmarkData(){return state.benchmarkDataset==='v4'&&D.comparison_v4?D.comparison_v4:D.comparison;}
const benchmarkViewNames={yapisal:'Yapısal',gecikmeli:'Geçmiş bakiyeli',hareketli:'Hareket + ay sonu'};
const algorithmColors={ay_sonu_koru:'#5d6884',lightgbm:'#3e6389',random_forest:'#7a68a2',catboost:'#bd9149',son_ayi_koru:'#82909e',egitim_ortalamasi:'#b5bdc5'};
function benchmarkRows(){
  const C=benchmarkData(),pool=state.group==='ALL'?C.total_metrics:C.metrics;
  return [...Object.keys(algorithms).map(a=>({key:a,label:algorithms[a],algorithm:a,
    score:pool.find(x=>x.gosterge===state.target&&x.model===a+'__'+state.benchmarkView&&x.split===state.split&&(state.group==='ALL'||x.sube_grubu===state.group))})),
    ...(C.manifest.baselines||['son_ayi_koru','egitim_ortalamasi']).map(a=>({key:a,label:models[a],algorithm:'referans',
    score:pool.find(x=>x.gosterge===state.target&&x.model===a&&x.split===state.split&&(state.group==='ALL'||x.sube_grubu===state.group))}))];
}
function benchmarkMetadata(algorithm){return benchmarkData().model_metadata.filter(x=>x.algoritma===algorithm&&x.gorunum===state.benchmarkView&&x.gosterge===state.target&&currentGroups().includes(x.sube_grubu));}
function benchmarkFit(algorithm){return benchmarkData().metrics.filter(x=>x.algoritma===algorithm&&x.gorunum===state.benchmarkView&&x.gosterge===state.target&&x.split===state.split&&currentGroups().includes(x.sube_grubu)).reduce((sum,x)=>sum+x.egitim_saniye,0);}
function benchmarkTuning(algorithm){return benchmarkMetadata(algorithm).reduce((sum,x)=>sum+x.tuning_seconds,0);}
function benchmarkBars(rows,field='wape'){
  const max=Math.max(...rows.map(x=>field==='wape'?x.score.wape:benchmarkFit(x.key)))*1.1||1;
  return rows.map(r=>{const v=field==='wape'?r.score.wape:benchmarkFit(r.key);return `<div class="comparison-row"><span class="model-label"><i class="legend-dot" style="background:${algorithmColors[r.key]}"></i>${esc(r.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${v/max*100}%;background:${algorithmColors[r.key]}"></div></div><strong>${field==='wape'?pct(v):nf(v,3)+' sn'}</strong></div>`;}).join('');
}
function benchmarkLineChart(){
  const C=benchmarkData(),keys=[...Object.keys(algorithms),'son_ayi_koru',...(C.manifest.baselines?.includes('ay_sonu_koru')?['ay_sonu_koru']:[])];
  const periods=[...new Set(C.monthly_metrics.map(x=>x.hedef_donemi))].sort();
  const value=(a,p)=>C.monthly_metrics.find(x=>x.gosterge===state.target&&x.model===(algorithms[a]?a+'__'+state.benchmarkView:a)&&x.sube_grubu===state.group&&x.hedef_donemi===p).wape;
  const max=Math.max(...keys.flatMap(a=>periods.map(p=>value(a,p))))*1.15;
  const W=900,H=260,L=57,R=20,T=20,B=40,xx=i=>L+(W-L-R)*i/5,yy=v=>T+(H-T-B)*(1-v/max);
  return `<svg class="line-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Üç algoritma ve son ay referansı için aylık WAPE">${Array.from({length:5},(_,i)=>{let v=max*i/4;return `<line x1="${L}" x2="${W-R}" y1="${yy(v)}" y2="${yy(v)}" stroke="#edf1f4"/><text x="${L-9}" y="${yy(v)+4}" text-anchor="end" fill="#8b9aa6" font-size="10">${pct(v,1)}</text>`;}).join('')}${periods.map((p,i)=>`<text x="${xx(i)}" y="${H-12}" text-anchor="middle" fill="#8b9aa6" font-size="11">${p}</text>`).join('')}${keys.map(a=>`<polyline points="${periods.map((p,i)=>`${xx(i)},${yy(value(a,p))}`).join(' ')}" fill="none" stroke="${algorithmColors[a]}" stroke-width="2" ${a==='son_ayi_koru'?'stroke-dasharray="5 5"':''}/>${periods.map((p,i)=>`<circle cx="${xx(i)}" cy="${yy(value(a,p))}" r="3.2" fill="${algorithmColors[a]}"><title>${algorithms[a]||models[a]} · ${p} · ${pct(value(a,p))}</title></circle>`).join('')}`).join('')}</svg><div class="chart-legend">${keys.map(a=>`<span><i class="legend-dot" style="background:${algorithmColors[a]}"></i>${algorithms[a]||models[a]}</span>`).join('')}</div>`;
}
function benchmarkImportance(){
  const a=state.benchmarkAlgorithm,metric=state.benchmarkImportance;
  const rows=benchmarkData().importance.filter(x=>x.algoritma===a&&x.gorunum===state.benchmarkView&&x.gosterge===state.target&&currentGroups().includes(x.sube_grubu));
  const field=metric==='permutation'?'normalize_delta_mae':'native_importance_pct';
  const nativeNames={lightgbm:'Gain',random_forest:'Safsızlık azalması',catboost:'PredictionValuesChange'};
  const label=metric==='permutation'?'Normalize ΔMAE':nativeNames[a]+' (%)';
  const format=v=>metric==='permutation'?pct(v):nf(v,2)+'%';
  return `<section class="card space-bottom"><div class="card-head"><div><h2>Üç algoritmada değişken önemi</h2><p>Önceki karşılaştırma modelleri · ortak FLAML modelinin önemleri yeniden hesaplanmadı.</p></div></div><div class="card-body"><div class="controls-row"><label class="local-select">Algoritma<select id="benchmark-algorithm">${Object.entries(algorithms).map(([key,name])=>`<option value="${key}" ${key===a?'selected':''}>${name}</option>`).join('')}</select></label><label class="local-select">Yöntem<select id="benchmark-importance"><option value="permutation" ${metric==='permutation'?'selected':''}>Permutation importance · ortak ölçü</option><option value="native" ${metric==='native'?'selected':''}>Modelin kendi önem ölçüsü</option></select></label></div><p class="inline-note">Modelleri özellik katkısı açısından karşılaştırmak için ortak permutation ölçüsünü kullanın. Gain, Random Forest safsızlık azalması ve CatBoost PredictionValuesChange farklı tanımlardır; kendi aralarında eşdeğer puan değildir.${state.benchmarkView!=='yapisal'?' Native önem yalnızca değişimi öğrenen modele aittir; dışarıdan eklenen mevcut bakiyeyi kapsamaz.':''}</p></div></section><div class="group-panels">${currentGroups().map(group=>{
      const top=rows.filter(x=>x.sube_grubu===group&&x.ozellik_grubu!=='takvim').sort((x,y)=>y[field]-x[field]).slice(0,9);
      const max=Math.max(...top.map(x=>Math.abs(x[field])),.00001)*1.1;
      return `<section class="card"><div class="card-head"><div><h2>${groups[group]}</h2><p>${algorithms[a]} · ${label}</p></div>${badge(String(benchmarkData().manifest.feature_counts[state.benchmarkView])+' alan','model')}</div><div class="importance-block">${top.map(r=>`<div class="importance-row"><span class="feature-label" title="${esc(r.alan_veya_grup)}">${esc(featureLabels[r.alan_veya_grup]||r.alan_veya_grup)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,r[field])/max*100}%;background:${algorithmColors[a]}"></div></div><strong>${format(r[field])}</strong></div>`).join('')}<p class="importance-note">Takvim dışındaki ilk 9 alan. Tüm sıfır ve negatif değerler aşağıdaki tabloda.</p></div></section>`;
    }).join('')}</div><section class="card"><div class="card-head"><div><h2>${algorithms[a]} · tüm özellikler</h2><p>${state.benchmarkDataset==='v4'?'Bu V4 koşusunda dönemler arası özellik kararlılığı ölçülmedi.':'Üç dönemlik kararlılık ilk V3 LightGBM çalışmasında ölçüldü; RF/CatBoost için ölçülmedi.'}</p></div><span class="count-label">${rows.length} kayıt</span></div><div class="table-wrap benchmark-importance-table"><table class="data-table"><thead><tr><th>Değişken</th><th>Şube grubu</th><th class="num">${label}</th><th class="num">ΔMAE · TL</th><th class="num">Tekrar std. · TL</th></tr></thead><tbody>${rows.sort((x,y)=>y[field]-x[field]).map(r=>`<tr><td>${esc(featureLabels[r.alan_veya_grup]||r.alan_veya_grup)}<span class="sub mono">${esc(r.alan_veya_grup)}</span></td><td>${groups[r.sube_grubu]}</td><td class="num">${format(r[field])}</td><td class="num">${nf(r.delta_mae_tl,2)}</td><td class="num">${nf(r.delta_mae_std_tl,2)}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function benchmarkPage(){
  if(!benchmarkData())return '<div class="empty-state">Karşılaştırma çalışması henüz yüklenmedi.</div>';
  const rows=benchmarkRows(),trained=rows.filter(r=>r.algorithm!=='referans');
  const winner=rows.reduce((a,b)=>a.score.wape<b.score.wape?a:b);
  const fastest=trained.reduce((a,b)=>benchmarkFit(a.key)<benchmarkFit(b.key)?a:b);
  const bestML=trained.reduce((a,b)=>a.score.wape<b.score.wape?a:b);
  const C=benchmarkData(),view=benchmarkViewNames[state.benchmarkView]+' · '+C.manifest.feature_counts[state.benchmarkView]+' alan';
  return `<div class="benchmark-content"><p class="inline-note">Bu ekran önceki V3/V4 karşılaştırma modellerini gösterir. Güncel ortak ${currentAlgorithm()} seçimi ve sonuçları <a class="link-button" href="#automl">FLAML AutoML</a> ekranındadır. Değişken önemleri bu karşılaştırma modellerine aittir.</p><div class="controls-row benchmark-controls"><label class="local-select">Veri ve deney<select id="benchmark-dataset"><option value="v4" ${state.benchmarkDataset==='v4'?'selected':''} ${D.comparison_v4?'':'disabled'}>V4 · Aylık müşteri hareketleri</option><option value="v3" ${state.benchmarkDataset==='v3'?'selected':''}>V3 · Önceki deney</option></select></label><label class="local-select">Özellik görünümü<select id="benchmark-view">${Object.entries(C.manifest.feature_counts).map(([key,n])=>`<option value="${key}" ${state.benchmarkView===key?'selected':''}>${benchmarkViewNames[key]} · ${n} alan</option>`).join('')}</select></label><span class="badge success">3 algoritma · ${C.manifest.models} model · ${C.manifest.saved_models} kayıtlı dosya</span><button class="button secondary small" id="export-benchmark">${icon('download',14)} Karşılaştırmayı indir</button></div><div class="metric-strip"><div class="metric-cell"><small>En düşük hata · referanslar dahil</small><strong>${esc(winner.label)}</strong><div class="metric-desc">WAPE ${pct(winner.score.wape)} · seçili görünüm</div></div><div class="metric-cell"><small>Üç algoritma içinde en düşük hata</small><strong>${esc(bestML.label)}</strong><div class="metric-desc">WAPE ${pct(bestML.score.wape)}</div></div><div class="metric-cell"><small>En kısa seçili fit süresi</small><strong>${esc(fastest.label)}</strong><div class="metric-desc">${nf(benchmarkFit(fastest.key),3)} sn · ${state.group==='ALL'?'iki grubun toplamı':'seçili grup'}</div></div></div><div class="two-col"><section class="card"><div class="card-head"><div><h2>Aynı koşullarda hata</h2><p>${metricContext()} · ${view}</p></div>${badge('WAPE','model')}</div><div class="card-body">${benchmarkBars(rows)}<p class="footnote">Daha düşük daha iyi. Her modelin ayarı doğrulama MAE ile seçildi. Test, ayar veya özellik seçiminde kullanılmadı.</p></div></section><section class="card"><div class="card-head"><div><h2>Eğitim süresi</h2><p>${state.split==='TEST'?'Eğitim + doğrulama ile test modeli yeniden eğitimi':'Seçilmiş doğrulama modelinin eğitim süresi'} · 2 CPU iş parçacığı</p></div>${icon('clock',17)}</div><div class="card-body">${benchmarkBars(trained,'fit')}<p class="footnote">Tek yerel ölçüm. RF kategori dönüştürücüsü fit süresine dahildir. Ayar araması, önem hesabı ve dosya kaydı bu çubuklara dahil değildir.</p></div></section></div><section class="card space-bottom"><div class="card-head"><div><h2>Hata ve hız karşılaştırması</h2><p>${view}. Tutarlar TL; grup WAPE’leri ortalanmaz.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Model</th><th class="num">WAPE</th><th class="num">MAE · TL</th><th class="num">RMSE · TL</th><th class="num">R²</th><th class="num">Toplam sapması</th><th class="num">Fit · sn</th><th class="num">3 aday araması · sn</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.label}${r.key===winner.key?'<span class="badge-best">En düşük hata</span>':''}</td><td class="num">${pct(r.score.wape)}</td><td class="num">${nf(r.score.mae_tl)}</td><td class="num">${nf(r.score.rmse_tl)}</td><td class="num">${nf(r.score.r2,3)}</td><td class="num">${pct(r.score.toplam_sapma_orani)}</td><td class="num">${r.algorithm==='referans'?'—':nf(benchmarkFit(r.key),3)}</td><td class="num">${r.algorithm==='referans'?'—':nf(benchmarkTuning(r.key),3)}</td></tr>`).join('')}</tbody></table></div></section><section class="card space-bottom"><div class="card-head"><div><h2>Aylara göre WAPE</h2><p>Temmuz–Eylül doğrulama; Ekim–Aralık ayrı test. Her biri bir ay ileri tahmindir.</p></div></div><div class="chart-panel">${benchmarkLineChart()}</div></section><details class="card benchmark-details space-bottom"><summary>Seçilen ayarlar ve model dosyaları</summary><div class="table-wrap"><table class="data-table"><thead><tr><th>Algoritma</th><th>Şube grubu</th><th>Ayar</th><th class="num">Ağaç</th><th class="num">Test eğitimi</th><th class="num">Ocak eğitimi</th></tr></thead><tbody>${Object.keys(algorithms).flatMap(a=>benchmarkMetadata(a).map(m=>`<tr><td>${algorithms[a]}</td><td>${groups[m.sube_grubu]}</td><td><span class="mono">${esc(JSON.stringify(m.best_config))}</span></td><td class="num">${m.n_estimators}</td><td class="num">${nf(m.eval_training_rows)}</td><td class="num">${nf(m.production_training_rows)}</td></tr>`)).join('')}</tbody></table></div></details>${benchmarkImportance()}<p class="inline-note section-break">Tüm karşılaştırma çalışması: ${nf(benchmarkData().manifest.pipeline_seconds,1)} sn; arama, önem, kaydetme ve Ocak modelleri dahil. Sonuçlar sentetik veriye aittir. V3 ve V4 farklı veri üretimlerine aittir; hata farkı gerçek banka başarısında artış kanıtı değildir. <a class="link-button" href="downloads/${state.benchmarkDataset==='v4'?'v4_karsilastirma_metodoloji.md':'karsilastirma_metodoloji.md'}" download>Karşılaştırma metodolojisi ${icon('download',13)}</a></p></div>`;
}
function exportBenchmark(){
  const rows=benchmarkRows();
  const lines=[['veri_surumu','gosterge','sube_grubu','split','gorunum','algoritma','n','wape','mae_tl','rmse_tl','r2','toplam_sapma_orani','fit_saniye','arama_saniye'],...rows.map(r=>[state.benchmarkDataset,state.target,state.group,state.split,state.benchmarkView,r.key,r.score.n,r.score.wape,r.score.mae_tl,r.score.rmse_tl,r.score.r2,r.score.toplam_sapma_orani,r.algorithm==='referans'?0:benchmarkFit(r.key),r.algorithm==='referans'?0:benchmarkTuning(r.key)])];
  const csv='\ufeff'+lines.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');
  a.href=url;a.download=`algoritma_karsilastirma_${state.benchmarkDataset}_${state.target}_${state.group}_${state.split}_${state.benchmarkView}.csv`;a.click();
  setTimeout(()=>URL.revokeObjectURL(url),5000);showToast('Algoritma karşılaştırması CSV olarak indiriliyor.');
}

function showToast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}

function fillIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon,el.closest('.button')?14:16));}
function updateStudyStatus(){const node=$('#latest-study');if(!node)return;node.classList.remove('study-blocked');if(selectionBlocked){node.classList.add('study-blocked');const a=D.auto_cluster_selection;node.hidden=false;node.innerHTML=`<div><strong>Kalite koşullarını sağlayan ortak model yok</strong><span>${nf(a.manifest.source_branch_count)} kaynak şube · ${a.candidates.filter(r=>r.qualified).length} uygun aday</span><small>Yeni atama ve DEA durduruldu. Şube eleme ve önceki modele otomatik dönüş yapılmaz. Önceki DEA hesapları tarihsel olarak incelenebilir.</small></div><a class="button secondary small" href="#model-selection">Grup koşullarını incele</a>`;return;}if(D.dea?.active){const d=D.dea,s=d.summary;node.hidden=false;node.innerHTML=`<div><strong>DEA verimlilik analizi tamamlandı</strong><span>${esc(d.manifest.as_of)} · ${nf(s.calculated_branches)} şube · ${nf(s.eligible_clusters)} emsal kümesi · ${nf(s.strongly_efficient)} etkin sınırda</span><small>Sıradaki aşama: banka hedefini şubelere dağıtma. DEA projeksiyonları henüz şube hedefi değildir.</small></div><a class="button secondary small" href="#dea">Verimliliği incele</a>`;return;}const raw=D.clustering?.matches_current_selection?D.clustering:null;const c=raw?window.resolveClusteringData(raw,{}):null;const f=D.feature_selection;node.hidden=!f&&!c;if(c){const m=c.manifest,auto=c.automatic_selection,w=auto?.decision.selected,method=auto?w?.method:m.primary_method;const total=c.selected.filter(r=>r.method===method).reduce((a,r)=>a+r.k,0);node.innerHTML=`<div><strong>Şube kümeleme tamamlandı</strong><span>${method?esc(c.method_names[method]):'Uygun ana model yok'} · ${nf(m.latest_branch_count)} şube · ${nf(total)} referans kümesi · ${nf(m.feature_count)} ortak alan</span><small>${auto&&!w?'Ana modelle atama için kalite koşulları sağlanmalı.':'Sıradaki aşama: DEA tasarımı.'} Verimlilik ve şube hedef dağıtımı henüz hesaplanmadı.</small></div><a class="button secondary small" href="#model-selection">Ana model seçimini incele</a>`;return;}if(!f)return;const m=f.manifest;node.innerHTML=`<div><strong>Değişken seçimi tamamlandı</strong><span>${nf(m.candidate_count)} aday · ${nf(m.selected_count)} seçilen alan · ${nf(m.latest_branch_count)} şube · ${esc(m.as_of)}</span><small>Sıradaki aşama: kümeleme. Kümeler henüz oluşturulmadı.</small></div><a class="button secondary small" href="#selection">Güncel çalışmayı aç</a>`;}

function render(){updateStudyStatus();const active=document.activeElement?.id;const caret=document.activeElement?.selectionStart;const [title,subtitle]=headings[state.route];$('#page-title').textContent=title;$('#page-subtitle').textContent=subtitle;$('#breadcrumb-current').textContent=nav.find(x=>x[0]===state.route)[2];$('#navigation').innerHTML=nav.map(([route,ic,label])=>`<a href="#${route}" ${route===state.route?'class="active" aria-current="page"':''}>${icon(ic,17)}${label}${route===state.route?'<span class="nav-dot"></span>':''}</a>`).join('');$('.filters').hidden=['methodology','data','files','selection','clustering','model-selection','dea'].includes(state.route);$('#target-select').value=state.target;$('#group-select').value=state.group;$('#split-select').value=state.split;$('.run-tag').innerHTML=`<span class="run-indicator"></span><div>${state.route==='dea'?'Küme içi CRS-DEA':state.route==='model-selection'?'Performansa göre kümeleme seçimi':state.route==='clustering'?'Ana yöntem ve alternatif kümeler':state.route==='selection'?'Sözlükten dinamik seçim':state.route==='automl'?'V4 FLAML AutoML':state.route==='benchmark'?state.benchmarkDataset.toUpperCase()+' model karşılaştırması':'V4 · Ortak '+currentAlgorithm()+' modeli'}<small>${state.route==='clustering'&&D.clustering?'Referans: '+esc(D.clustering.manifest.reference_period):state.route==='selection'&&D.feature_selection?'Veri sonu: '+esc(D.feature_selection.manifest.as_of):'Kasım 2024 – Aralık 2026'}</small></div>`;const packageLink=$('.topbar-right a.button');if(packageLink)packageLink.href=state.route==='dea'?'downloads/dea_package.zip':state.route==='model-selection'?'downloads/auto_cluster_package.zip':state.route==='clustering'?(D.auto_cluster_selection?.matches_current_grid?'downloads/auto_cluster_package.zip':'downloads/clustering_package.zip'):state.route==='selection'?'downloads/selection_package.zip':state.route==='automl'?'downloads/flaml_v4_paketi.zip':state.route==='benchmark'?(state.benchmarkDataset==='v4'?'downloads/model_karsilastirma_v4_paketi.zip':'downloads/model_karsilastirma_paketi.zip'):'downloads/flaml_v4_paketi.zip';const views={dea:()=>window.renderDEAPage(D.dea,state),'model-selection':()=>window.renderClusterSelectionPage(D.auto_cluster_selection),clustering:()=>window.renderClusteringPage(D.clustering,state),selection:()=>window.renderSelectionPage(D.feature_selection,state),automl:()=>window.renderFlamlPage(D.automl,state),benchmark:benchmarkPage,overview,pipeline,methodology,data:dataPage,files:filesPage};$('#content').innerHTML=views[state.route]();fillIcons();if(active&&document.getElementById(active)){const el=document.getElementById(active);el.focus({preventScroll:true});if(typeof caret==='number'&&el.setSelectionRange&&el.type==='search')el.setSelectionRange(caret,caret);}document.title=`${title} · Hedef`}
function routeChanged(){const raw=location.hash.replace('#','').split('?')[0];const key=({results:'benchmark',importance:'benchmark'})[raw]||raw||(D.dea?.active?'dea':D.auto_cluster_selection?.matches_current_grid?'model-selection':D.clustering?.matches_current_selection?'clustering':D.feature_selection?'selection':D.automl?'automl':D.comparison_v4?'benchmark':'overview');if(key==='main-content')return;state.route=headings[key]?key:'overview';render();window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('change',event=>{const id=event.target.id,v=event.target.value;if(id==='dea-group'){state.deaGroup=v;state.deaCluster='ALL';state.deaBranch='';}else if(id==='dea-cluster'){state.deaCluster=v;state.deaBranch='';}else if(id==='dea-indicator')state.deaIndicator=v;else if(id==='dea-branch')state.deaBranch=v;else if(id==='cluster-scenario'){state.clusterScenario=v;state.clusterSearch='';}else if(id==='cluster-method')state.clusterMethod=v;else if(id==='cluster-group')state.clusterGroup=v;else if(id==='cluster-period')state.clusterPeriod=v;else if(id==='selection-status')state.selectionStatus=v;else if(id==='selection-family')state.selectionFamily=v;else if(id==='benchmark-dataset'){state.benchmarkDataset=v;if(!(state.benchmarkView in benchmarkData().manifest.feature_counts))state.benchmarkView='gecikmeli';}else if(id==='benchmark-view')state.benchmarkView=v;else if(id==='benchmark-algorithm')state.benchmarkAlgorithm=v;else if(id==='benchmark-importance')state.benchmarkImportance=v;else if(id==='target-select')state.target=v;else if(id==='group-select')state.group=v;else if(id==='split-select')state.split=v;else return;render();});
document.addEventListener('input',event=>{if(event.target.id==='dea-search'){state.deaSearch=event.target.value;state.deaBranch='';render();return;}if(event.target.id==='cluster-search'){state.clusterSearch=event.target.value;render();return;}if(event.target.id==='selection-search'){state.selectionSearch=event.target.value;render();}});
document.addEventListener('click',event=>{const open=event.target.closest('[data-open-step]');if(open){state.step=Number(open.dataset.openStep);location.hash='pipeline';return;}const stage=event.target.closest('[data-stage]');if(stage){state.step=Number(stage.dataset.stage);render();return;}if(event.target.closest('#reset-filters')){Object.assign(state,{deaGroup:'ALL',deaCluster:'ALL',deaIndicator:'',deaSearch:'',deaBranch:'',target:'tl_vadesiz',group:'ALL',split:'TEST',selectionStatus:'all',selectionFamily:'all',selectionSearch:'',clusterGroup:'ALL',clusterMethod:'',clusterPeriod:'',clusterSearch:'',clusterScenario:''});render();showToast('Filtreler başlangıç görünümüne alındı.');return;}if(event.target.closest('#export-clustering')){window.exportClusteringTable(D.clustering,state);showToast('Seçili şube küme atamaları indiriliyor.');return;}if(event.target.closest('#export-selection')){window.exportSelectionTable(D.feature_selection,state);showToast('Değişken seçimi kararları CSV olarak indiriliyor.');return;}if(event.target.closest('#export-flaml')){window.exportFlamlTable(D.automl,state);showToast('Seçili AutoML sonuçları CSV olarak indiriliyor.');return;}if(event.target.closest('#export-benchmark')){exportBenchmark();return;}});
window.addEventListener('hashchange',routeChanged);
if(!D?.automl?.global_selection||!D.data_manifest_v4){$('#content').innerHTML='<div class="empty-state">Çalışma verisi yüklenemedi. Sayfayı yenileyin.</div>';return;}
routeChanged();
})();
